// Included once by Expansion.cpp. Import adapters use the same NoCTRL DSP as the editable FX rack.
namespace noctrl {
String describeImportedFx(const Expansion& e){String result;const char* names[]={"MAIN","BUS 1","BUS 2"};for(auto& effect:e.fx){result+=String(names[jlimit(0,2,effect.rack)])+" / "+String(effect.sourceIndex+1)+"  "+effect.type+(effect.enabled?"":" [bypass]");if(effect.nativeType>=12&&effect.nativeType<=14)result+="  branches: "+String((int)effect.value("kParamModuleCount1",0))+" / "+String((int)effect.value("kParamModuleCount2",0))+(effect.nativeType==13?" / "+String((int)effect.value("kParamModuleCount3",0)):"");result+="\n";}return result+"\n"+String(e.fxMods.size())+" per-effect modulation routes.\nImported FX precede your additional rack effects. NoCTRL algorithms approximate the original sound.";}
void configureImportedFx(FxExtra& x){
 const std::map<String,int> types={{"FXBode",0},{"FXChorus",1},{"FXComp",2},{"FXCompressor",2},{"FXConvolve",3},{"FXDelay",4},{"FXDistortion",5},{"FXEQ",6},{"FXFilter",7},{"FXFlanger",8},{"FXHyperD",9},{"FXPhaser",10},{"FXReverb",11},{"FXSplit",12},{"FXSplit3",13},{"FXSplitLMH",13},{"FXSplitMS",14},{"FXUtility",15}};
 auto found=types.find(x.type);if(found==types.end())return;x.nativeType=found->second;
 if(x.type=="FXSplit"&&(x.params.count("kParamFreq2")||x.value("kParamBands",2)>2))x.nativeType=13;
 auto& def=fxDefinitions()[x.nativeType];for(size_t i=0;i<def.controls.size();++i)x.controls[i]=def.controls[i].to(def.controls[i].initial);x.controls[8]=(float)x.value("kParamWet",100)/100;
 auto n=[&](String key,float fallback){return (float)x.value(key,fallback);};auto put=[&](int c,float value){auto& parameter=def.controls[(size_t)c];x.controls[c]=jlimit(0.f,1.f,parameter.to(jlimit(parameter.lo,parameter.hi,value)));};
 auto map=[&](String key,int target){x.targets[key]=target;};map("kParamWet",8);
 if(x.nativeType==0){x.controls[9]=n("kParamRange",50)/1000;x.controls[10]=n("kParamShift",0)/100;put(0,x.controls[9]*1000*x.controls[10]);put(1,n("kParamStereo",0)/100);map("kParamRange",9);map("kParamShift",10);map("kParamOutputWidth",1);}
 if(x.nativeType==1){put(0,n("kParamRate",.3f));put(1,n("kParamDepth",35)/100);put(2,n("kParamDelay",12));put(3,n("kParamFeedback",10)/100);map("kParamRate",0);map("kParamDepth",1);map("kParamDelay",2);map("kParamFeedback",3);x.controls[9]=jlimit(0.f,1.f,std::log(jlimit(20.f,20000.f,n("kParamFilt",20000))/20)/std::log(1000.f));map("kParamFilt",9);}
 if(x.nativeType==2){put(0,-60+60*n("kParamThresh",.5f));put(1,n("kParamRatio",4));put(2,n("kParamAttack",10));put(3,n("kParamRelease",100));put(4,Decibels::gainToDecibels(jmax(.01f,n("kParamMakeup",1))));for(int b=0;b<3;++b){x.controls[9+b]=(n("kParamGain"+String(b),0)+18)/36;x.controls[12+b]=n("kParamThreshUD"+String(b),50)/100;map("kParamGain"+String(b),9+b);map("kParamThreshUD"+String(b),12+b);}x.controls[15]=n("kParamMultiband",0);map("kParamThresh",0);map("kParamRatio",1);map("kParamAttack",2);map("kParamRelease",3);map("kParamMakeup",4);}
 if(x.nativeType==3){put(0,n("kParamPreDelay",0)*1000);put(1,n("kParamDamp",18000));put(2,n("kParamWidth",100)/100);put(3,n("kParamGain",0));map("kParamPreDelay",0);map("kParamDamp",1);map("kParamWidth",2);map("kParamGain",3);}
 if(x.nativeType==4){put(0,n("kParamTimeL",.25f)*1000);put(1,n("kParamFeedback",35)/100);put(2,n("kParamMode",0)>.5f?1:0);float center=n("kParamFreq",5000),bw=n("kParamBW",4);put(3,center/std::pow(2.f,bw*.5f));put(4,center*std::pow(2.f,bw*.5f));x.controls[9]=jlimit(0.f,1.f,def.controls[0].to(jlimit(1.f,2000.f,n("kParamTimeR",.25f)*1000)));map("kParamTimeL",0);map("kParamTimeR",9);map("kParamFeedback",1);map("kParamFreq",4);map("kParamBW",3);}
 if(x.nativeType==5){put(0,n("kParamDrive",25)*.36f);auto mode=x.document.getProperty("plainParams",{}).getProperty("kParamMode","kSoftSat").toString();put(1,mode=="kDownsample"?4:mode=="kSineShaper"?3:mode=="kTapeSat"?2:mode=="kStompBox"?1:0);float freq=n("kParamFreq",.8f);put(2,freq<=1?20*std::pow(1000.f,freq):freq);put(3,0);map("kParamDrive",0);map("kParamFreq",2);map("kParamLevelOut",3);}
 if(x.nativeType==6){for(int b=0;b<2;++b){x.controls[b*2]=jlimit(0.f,1.f,std::log(jlimit(20.f,20000.f,n("kParamFreq"+String(b+1),b?6000:200))/20)/std::log(1000.f));x.controls[b*2+1]=(n("kParamGain"+String(b+1),0)+24)/48;x.controls[4+b]=n("kParamReso"+String(b+1),30)/100;x.controls[6+b]=n("kParamType"+String(b+1),0);map("kParamFreq"+String(b+1),b*2);map("kParamGain"+String(b+1),b*2+1);map("kParamReso"+String(b+1),4+b);}}
 if(x.nativeType==7){float freq=n("kParamFreq",.5f);put(0,freq<=1?20*std::pow(1000.f,freq):freq);put(1,n("kParamReso",10)/100);auto mode=x.document.getProperty("plainParams",{}).getProperty("kParamType","L12").toString();put(2,mode.startsWithIgnoreCase("H")?1:mode.startsWithIgnoreCase("B")?2:mode.containsIgnoreCase("Notch")?3:0);put(3,n("kParamDrive",0)*.18f);map("kParamFreq",0);map("kParamReso",1);map("kParamDrive",3);x.controls[4]=n("kParamStereo",100)/200;map("kParamStereo",4);}
 if(x.nativeType==8||x.nativeType==10){put(0,jmax(.01f,n("kParamRate",.2f)));put(1,n("kParamDepth",50)/100);if(x.nativeType==8){put(2,2);put(3,jlimit(-.9f,.9f,n("kParamFeedback",30)/100));put(4,n("kParamWidth",50)/200);}else{put(2,n("kParamFreq",1000));put(3,n("kParamFeedback",20)/100);}map("kParamRate",0);map("kParamDepth",1);map("kParamFreq",2);map("kParamFeedback",3);if(x.nativeType==8)map("kParamWidth",4);}
 if(x.nativeType==9){put(0,n("kParamRate",40)/100);put(1,n("kParamDetune",35)/100);put(2,n("kParamWet",0)/100);put(3,1+n("kParamDimESize",30)*.39f);put(4,n("kParamDimEWet",0)/100);put(5,1);x.controls[8]=1;map("kParamWet",2);map("kParamDimEWet",4);map("kParamDimESize",3);map("kParamRate",0);map("kParamDetune",1);}
 if(x.nativeType==11){put(0,n("kParamSize",70)/100);put(1,n("kParamDamp",50)/100);put(2,n("kParamPreDelay",.01f)*1000);put(3,n("kParamWidth",100)/100);put(4,20*std::pow(100.f,n("kParamFreq",0)/100));put(5,20000/std::pow(20.f,n("kParamFreqB",0)/100));map("kParamSize",0);map("kParamDamp",1);map("kParamPreDelay",2);map("kParamWidth",3);map("kParamFreq",4);map("kParamFreqB",5);x.controls[6]=n("kParamDelay",73)/100;map("kParamDelay",6);}
 if(x.nativeType==12||x.nativeType==13){put(0,n("kParamFreq",x.nativeType==12?1000:300));if(x.nativeType==13)put(1,n("kParamFreq2",3000));map("kParamFreq",0);if(x.nativeType==13)map("kParamFreq2",1);}
 if(x.nativeType==14){put(0,n("kParamGain1",0));put(1,n("kParamGain2",0));put(2,n("kParamWidth",100)/100);map("kParamGain1",0);map("kParamGain2",1);map("kParamWidth",2);}
 if(x.nativeType==15){put(0,n("kParamGain",0));put(1,n("kParamPan",0)/100);put(2,n("kParamWidth",100)/100);map("kParamGain",0);map("kParamPan",1);map("kParamWidth",2);}
}
struct ImportBiquad {std::array<float,6> coefficients{{1,0,0,1,0,0}};float z1=0,z2=0;void reset(){z1=z2=0;}float processSample(float x){auto& c=coefficients;float y=c[0]/c[3]*x+z1;z1=c[1]/c[3]*x-c[4]/c[3]*y+z2;z2=c[2]/c[3]*x-c[5]/c[3]*y;return y;}};
struct ExpandedFx::Unit {
 FxExtra config;std::unique_ptr<NativeFxAdapter> dsp;AudioBuffer<float> dry{2,8192},bands[3],delay;int cursor=0,end=0;float low[2]={},high[2]={},filterLow[2]={},filterHigh[2]={},envelope[3]={};ImportBiquad eq[2][2];std::array<float,16> values{};std::array<std::array<float,128>,2> hilbert{};std::array<float,127> hilbertCoeff{};int hilbertCursor=0;double phase[2]={};
 Unit(){for(auto& band:bands)band.setSize(2,8192);}
};
ExpandedFx::ExpandedFx()=default;ExpandedFx::~ExpandedFx()=default;
void ExpandedFx::prepare(const Expansion& e,double rate,int,AudioProcessorValueTreeState& state){sr=rate;units.clear();for(auto& config:e.fx){auto u=std::make_unique<Unit>();u->config=config;u->values=config.controls;for(int k=0;k<127;++k){int t=k-63;u->hilbertCoeff[k]=t!=0&&std::abs(t)%2?2.f/(MathConstants<float>::pi*t)*(.54f-.46f*std::cos(MathConstants<float>::twoPi*k/126)):0;}u->dsp=std::make_unique<NativeFxAdapter>(jmax(0,config.nativeType),state,sr);if(config.nativeType==4||config.nativeType==0){u->delay.setSize(2,(int)(sr*4)+4);u->delay.clear();}units.push_back(std::move(u));}}
void ExpandedFx::reset(){for(auto& u:units){u->dsp->reset();u->delay.clear();u->cursor=u->hilbertCursor=0;u->phase[0]=u->phase[1]=0;for(auto& channel:u->hilbert)channel.fill(0);for(auto& f:u->low)f=0;for(auto& f:u->high)f=0;for(auto& f:u->filterLow)f=0;for(auto& f:u->filterHigh)f=0;for(auto& f:u->envelope)f=0;for(auto& band:u->eq)for(auto& f:band)f.reset();}}
void ExpandedFx::chain(AudioBuffer<float>& audio,int start,int count,int first,int finish,int bus,const std::array<float,1024>& mods,double bpm){
 for(int at=first;at<finish;++at){auto& u=*units[(size_t)at];auto& config=u.config;if(config.rack!=bus)continue;int type=config.nativeType;u.values=config.controls;for(int c=0;c<16;++c)u.values[c]+=mods[(size_t)at*16+c];auto& values=u.values;for(int c=0;c<9;++c)if(!(type==6&&(c==1||c==3||c>=6)))values[c]=jlimit(0.f,1.f,values[c]);auto physical=[&](int c){return fxDefinitions()[type].controls[c].from(values[c]);};auto pole=[&](float input,float hz,float& memory){float alpha=1-std::exp(-MathConstants<float>::twoPi*jlimit(20.f,(float)sr*.43f,hz)/(float)sr);memory+=alpha*(input-memory);return memory;};
  if(type==12||type==13||type==14){int counts[3]={(int)config.value("kParamModuleCount1",0),(int)config.value("kParamModuleCount2",0),(int)config.value("kParamModuleCount3",0)};int branches=type==13?3:2;int tail=at+1,rackEnd=at+1;while(rackEnd<finish&&units[(size_t)rackEnd]->config.rack==bus)++rackEnd;for(int b=0;b<branches;++b)tail+=jlimit(0,64,counts[b]);tail=jmin(tail,rackEnd);if(!config.enabled){at=tail-1;continue;}
   for(int c=0;c<2;++c)u.dry.copyFrom(c,0,audio,c,start,count);
   for(int i=0;i<count;++i){float l=audio.getSample(0,start+i),r=audio.getSample(1,start+i);if(type==14){float mid=(l+r)*.5f,side=(l-r)*.5f;u.bands[0].setSample(0,i,mid);u.bands[0].setSample(1,i,mid);u.bands[1].setSample(0,i,side);u.bands[1].setSample(1,i,-side);}else for(int c=0;c<2;++c){float x=audio.getSample(c,start+i),lo=pole(x,physical(0),u.low[c]);u.bands[0].setSample(c,i,lo);if(type==13){float upper=pole(x,jmax(physical(0),physical(1)),u.high[c]);u.bands[1].setSample(c,i,upper-lo);u.bands[2].setSample(c,i,x-upper);}else u.bands[1].setSample(c,i,x-lo);}}
   int child=at+1;for(int band=0;band<branches;++band){int end=jmin(tail,child+jlimit(0,64,counts[band]));chain(u.bands[band],0,count,child,end,bus,mods,bpm);child=end;}
   for(int c=0;c<2;++c)for(int i=0;i<count;++i){float sum=0;for(int band=0;band<branches;++band){float gain=type==14?Decibels::decibelsToGain(physical(band))*(band==1?physical(2):1):Decibels::decibelsToGain(physical((type==13?2:1)+band));sum+=u.bands[band].getSample(c,i)*gain;}float dry=u.dry.getSample(c,i);audio.setSample(c,start+i,dry+(sum-dry)*jlimit(0.f,1.f,values[8]));}at=tail-1;continue;
  }
  if(!config.enabled||type<0)continue;
  float wet=jlimit(0.f,1.f,values[8]);if(wet<=0)continue;
  if(type==6){for(int b=0;b<2;++b){float hz=20*std::pow(1000.f,jlimit(0.f,1.f,values[b*2])),gain=Decibels::decibelsToGain(-24+48*jlimit(0.f,1.f,values[b*2+1])),q=.2f+7.8f*jlimit(0.f,1.f,values[4+b]);int mode=roundToInt(values[6+b]);auto coefficients=mode==2?dsp::IIR::ArrayCoefficients<float>::makeHighPass(sr,jmin(hz,(float)sr*.43f),q):mode==1?dsp::IIR::ArrayCoefficients<float>::makeLowPass(sr,jmin(hz,(float)sr*.43f),q):dsp::IIR::ArrayCoefficients<float>::makePeakFilter(sr,jmin(hz,(float)sr*.43f),q,gain);for(int c=0;c<2;++c)u.eq[b][c].coefficients=coefficients;}
   for(int c=0;c<2;++c)for(int i=start;i<start+count;++i){float dry=audio.getSample(c,i),value=dry;for(int b=0;b<2;++b)value=u.eq[b][c].processSample(value);audio.setSample(c,i,dry+(value-dry)*wet);}continue;
  }
  if(type==2){float upRatios[3];for(int band=0;band<3;++band)upRatios[band]=jlimit(.01f,1.f,(float)config.value("kParamRatioBelow"+(band?String(band):String()),config.value("kParamRatioBelow",1)));bool multi=values[15]>.5f;int bands=multi?3:1;float downRatio=jmax(1.f,physical(1)),attack=physical(2),release=physical(3),makeup=physical(4),crossLow=(float)config.value("kParamXoverLow",250),crossHigh=(float)config.value("kParamXoverHigh",3500);for(int i=start;i<start+count;++i){float dry[2]={audio.getSample(0,i),audio.getSample(1,i)},split[3][2]={{dry[0],dry[1]}},out[2]={};if(multi)for(int c=0;c<2;++c){float lo=pole(dry[c],crossLow,u.low[c]),upper=pole(dry[c],crossHigh,u.high[c]);split[0][c]=lo;split[1][c]=upper-lo;split[2][c]=dry[c]-upper;}for(int band=0;band<bands;++band){float peak=jmax(std::abs(split[band][0]),std::abs(split[band][1])),coefficient=std::exp(-1.f/((float)sr*.001f*(peak>u.envelope[band]?attack:release)));u.envelope[band]=coefficient*u.envelope[band]+(1-coefficient)*peak;float db=Decibels::gainToDecibels(u.envelope[band],-100.f),threshold=physical(0)+(jlimit(0.f,1.f,values[12+band])-.5f)*48,up=upRatios[band];float gain=db>threshold?-(db-threshold)*(1-1/downRatio):(threshold-db)*(1-up);gain=jlimit(-60.f,24.f,gain);float amplitude=Decibels::decibelsToGain(gain+makeup+(multi?-18+36*jlimit(0.f,1.f,values[9+band]):0));for(int c=0;c<2;++c)out[c]+=split[band][c]*amplitude;}for(int c=0;c<2;++c)audio.setSample(c,i,dry[c]+(out[c]-dry[c])*wet);}continue;}
  if(type==4){int length=u.delay.getNumSamples();float feedback=jlimit(0.f,.95f,physical(1));float times[2]={physical(0),(float)fxDefinitions()[4].controls[0].from(jlimit(0.f,1.f,values[9]))};for(int c=0;c<2;++c){times[c]*=(float)config.value(c==0?"kParamOffsetL":"kParamOffsetR",1);times[c]=jlimit(1.f,(float)length-2,times[c]*.001f*(float)sr);}for(int i=start;i<start+count;++i){float taps[2],dry[2]={audio.getSample(0,i),audio.getSample(1,i)};for(int c=0;c<2;++c){double pos=std::fmod((double)u.cursor-times[c]+length,length);int k=jlimit(0,length-1,(int)pos);float fraction=(float)(pos-k);taps[c]=u.delay.getSample(c,k)*(1-fraction)+u.delay.getSample(c,(k+1)%length)*fraction;}for(int c=0;c<2;++c){float echo=taps[c]-pole(taps[c],physical(3),u.filterLow[c]);echo=pole(echo,physical(4),u.filterHigh[c]);u.delay.setSample(c,u.cursor,dry[c]+(physical(2)>.5f?taps[1-c]:taps[c])*feedback);audio.setSample(c,i,dry[c]+(echo-dry[c])*wet);}u.cursor=(u.cursor+1)%length;}continue;}
  if(type==0){float shift=jlimit(-1000.f,1000.f,values[9]*1000*values[10]),feedback=jlimit(-.95f,.95f,(float)config.value("kParamFeedback",0)/100),blur=jlimit(0.f,1.f,(float)config.value("kParamBlur",0)/100),balance=jlimit(0.f,1.f,((float)config.value("kParamDelayBalance",-100)+100)/200);float time=(float)config.value("kParamDelayTime",.025);if(config.value("kParamBeatSync",0)>.5)time*=(float)(60/bpm);int length=u.delay.getNumSamples(),offset=jlimit(1,length-1,(int)(time*sr));for(int i=start;i<start+count;++i){int read=(u.cursor-offset+length)%length;for(int c=0;c<2;++c){float dry=audio.getSample(c,i),echo=u.delay.getSample(c,read),input=dry+echo*feedback;u.hilbert[c][u.hilbertCursor]=input;float imaginary=0;for(int k=0;k<127;++k)imaginary+=u.hilbert[c][(u.hilbertCursor-k+128)%128]*u.hilbertCoeff[k];float real=u.hilbert[c][(u.hilbertCursor-63+128)%128];float shifted=real*(float)std::cos(u.phase[c])-imaginary*(float)std::sin(u.phase[c]);u.phase[c]=std::fmod(u.phase[c]+MathConstants<double>::twoPi*shift*(c==1?1+physical(1):1)/sr,MathConstants<double>::twoPi);float value=shifted*(1-balance)+echo*balance;if(blur>0)value=pole(value,20000*std::pow(.025f,blur),u.filterLow[c]);u.delay.setSample(c,u.cursor,jlimit(-8.f,8.f,shifted));audio.setSample(c,i,dry+(value-dry)*wet);}u.cursor=(u.cursor+1)%length;u.hilbertCursor=(u.hilbertCursor+1)%128;}continue;}
  if(type==1||type==7){for(int c=0;c<2;++c)u.dry.copyFrom(c,0,audio,c,start,count);values[8]=1;u.dsp->process(audio,start,count,values,bpm);for(int i=0;i<count;++i){float left=audio.getSample(0,start+i),right=audio.getSample(1,start+i);if(type==1&&values[9]<.9999f){float hz=20*std::pow(1000.f,jlimit(0.f,1.f,values[9]));left=pole(left,hz,u.filterLow[0]);right=pole(right,hz,u.filterLow[1]);}if(type==7){float mid=(left+right)*.5f,side=(left-right)*.5f*jlimit(0.f,2.f,values[4]*2);left=mid+side;right=mid-side;}audio.setSample(0,start+i,u.dry.getSample(0,i)+(left-u.dry.getSample(0,i))*wet);audio.setSample(1,start+i,u.dry.getSample(1,i)+(right-u.dry.getSample(1,i))*wet);}continue;}
  if(type==11)values[0]=jlimit(0.f,1.f,values[0]+(values[6]-config.controls[6])*.5f);
  u.dsp->process(audio,start,count,values,bpm);
 }
}
void ExpandedFx::process(AudioBuffer<float>& audio,int start,int count,const Settings& settings,int bus,const std::array<float,1024>* modulation){static const std::array<float,1024> zero{};chain(audio,start,count,0,(int)units.size(),bus,modulation?*modulation:zero,settings.bpm);}
}
